-- 9-xizmat: sayt, bot va ilovani tekshirish va texnik tavsif yozish. Yozuv bo'lsa (admin qo'shgan bo'lsa) tegilmaydi.
INSERT OR IGNORE INTO services(id,slug,data,published) VALUES('tekshiruv','tekshiruv','{"slug":"tekshiruv","number":"09","name":"Sayt, bot va ilovani tekshirish","short":"Sayt, bot yoki ilovangizni tekshirib, xatolarini aytamiz va tuzatish uchun texnik tavsif yozib beramiz.","description":"Sayt, Telegram bot yoki ilovangizni mijoz ko‘zi bilan va texnik tomondan tekshiramiz. Topilgan xatolarni tushunarli tilda aytamiz, ularni tuzatish uchun texnik tavsif yozib beramiz va tuzatish narxini hisoblaymiz. Tuzatishni xohlasangiz bizga, xohlasangiz boshqa dasturchiga berasiz. Bizga bersangiz, tekshiruv narxi tuzatish narxidan chegiriladi.","features":["Telefon va kompyuterda tekshirish: nima ishlamayapti va nima noqulay","Formalar, tugmalar, buyurtma va to‘lov jarayonini sinab ko‘rish","Tezlik va yuklanish vaqti","Xavfsizlik: SSL, eskirgan versiyalar, ochiq qolgan ma’lumotlar","Matn, rasm va havolalardagi xatolar","Har bir xato skrinshot bilan, muhimligi bo‘yicha tartiblangan","Har qanday dasturchi tushunadigan texnik tavsif","Tuzatish narxi va muddati"],"icon":"audit","promises":false,"published":true,"price":"100 000 so‘mdan","term":"3 ish kunigacha","packages":[{"name":"Sayt","price":"100 000 so‘mdan","term":"3 ish kunigacha","features":["Turli telefon va brauzerlarda ko‘rinish","Google va Yandex uchun asosiy sozlamalar: sarlavha, tavsif, sitemap"],"recommended":true,"fit":"Saytimni tekshirmoqchiman","hidden":false},{"name":"Telegram bot","price":"100 000 so‘mdan","term":"3 ish kunigacha","features":["Barcha menyu, tugma va qadamlarni bosib ko‘rish","Bot javob bermay qoladigan holatlar","Buyurtma va xabarnomalar to‘g‘ri yetib borishi"],"recommended":false,"fit":"Botimni tekshirmoqchiman","hidden":false},{"name":"Ilova","price":"100 000 so‘mdan","term":"3 ish kunigacha","features":["Brauzer yoki mobil ilovaning asosiy ish jarayonlari","Foydalanuvchilar, rollar va ruxsatlar","Ma’lumotlar zaxirasi va himoyalangan kirish"],"recommended":false,"fit":"Ilova yoki dasturimni tekshirmoqchiman","hidden":false}]}',1);
